sys_script_include.script:
var LabTestUtils = Class.create();
LabTestUtils.prototype = {
    initialize: function() {},
	sys: function(id) {
        var pat = new GlideRecord('u_patient_record');
        pat.addQuery('u_number', id);
        pat.query();
        pat.next();
        var sys = pat.getUniqueValue();
        return sys;
    },
    fetchTestResultsById: function(id) {
        var _results = new GlideRecord('u_lab_test');
        _results.addQuery('number', id);
        _results.query();
        if (_results.next()) {
            return "Result = " + _results.u_results;
        }

    },

    fetchTestResultsStatus: function(id) {
        var _status = new GlideRecord('u_lab_test');
        _status.addQuery('number', id);
        _status.query();
        if (_status.next()) {
            return "Results are = " + _status.u_status;
        }

    },

    fetchLabTestById: function(patientid) {
		var sysid= this.sys(patientid)
        var _test = new GlideRecord('u_lab_test');
        _test.addQuery('u_patient_id', sysid);
        _test.query();
        while (_test.next()) {
            return _test;
        }

    },

    fetchLabTestByDate: function(dateStr) {
        var _date = new GlideRecord('u_lab_test');
        _date.addQuery('u_schedule_date', 'CONTAINS', dateStr);
        _date.query();
        while (_date.next()) {
            return _date;
        }
    },

    type: 'LabTestUtils'
};
